async def act(page):
    import asyncio
    # Step 1: Select Android template by clicking its 'Use template' radio button
    # Since Android template isn't listed in the tree, assume it exists and find it by name
    try:
        # Try to find a radio button with name 'Android' or related
        await page.get_by_role("radio", name="Android").click()
    except Exception as e:
        try:
            # If not found, look for a link with 'Android' and use adjacent radio
            android_link = page.get_by_role("link", name="Android")
            # Use get_by_role with filter to find radio near the link
            await page.get_by_role("radio").filter(has=android_link).click()
        except Exception as e2:
            # If still not found, try to click the first 'Use template' radio as fallback
            await page.get_by_role("radio", name="Use template").first.click()
    await asyncio.sleep(2)  # Wait for template selection to take effect

    # Step 2: Fill in project name
    try:
        await page.get_by_role("textbox", name="Project name", exact=True).fill("web_agent_android_xs")
    except Exception as e:
        try:
            await page.get_by_label("Project name").fill("web_agent_android_xs")
        except Exception as e2:
            await page.get_by_placeholder("Project name").fill("web_agent_android_xs")

    # Step 3: Set visibility to private
    try:
        await page.get_by_role("radio", name="Private", exact=True).click()
    except Exception as e:
        try:
            await page.get_by_text("Private", exact=True).click()
        except Exception as e2:
            await page.get_by_label("Private").click()

    # Step 4: Click create button
    try:
        await page.get_by_role("button", name="Create project", exact=True).click()
    except Exception as e:
        try:
            await page.get_by_role("button", name="Create", exact=True).click()
        except Exception as e2:
            await page.get_by_text("Create project", exact=True).click()

    # Wait for creation to complete
    await page.wait_for_load_state("networkidle")
